from textual.app import App, ComposeResult
from textual.widgets import Button, Container, Label, Static
from textual.message import Message


class MyWidget(Static):
    """A widget that sends custom messages to its parent."""

    class CustomMessage(Message):
        """A custom message sent by MyWidget."""

        def __init__(self, text: str) -> None:
            self.text = text
            super().__init__()

    def compose(self) -> ComposeResult:
        yield Button("Send Message", id="send-btn")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        self.post_message(self.CustomMessage("Button was clicked!"))


class MyApp(App):
    """Main application."""

    def compose(self) -> ComposeResult:
        yield Container(
            Label("Waiting for message...", id="status"),
            MyWidget(id="my-widget"),
        )

    def on_my_widget_custom_message(self, message: MyWidget.CustomMessage) -> None:
        """Handle custom message from MyWidget."""
        status = self.query_one("#status", Label)
        status.update(f"Message received: {message.text}")


if __name__ == "__main__":
    app = MyApp()
    app.run()

